import type { NextConfig } from "next";

/**
 * Where the old API runs (`PMO-Legacy-API`, its own Next.js app).
 *
 * The browser keeps calling `/api/...` on this app's origin and Next forwards
 * the request there, so cookies, sign-in and CORS behave exactly as when the
 * API lived in this app. Screens move to the new backend one feature at a time;
 * once nothing calls `/api` any more, this rewrite and the legacy app go.
 */
const legacyApiUrl = (process.env.LEGACY_API_URL || "http://localhost:7061").replace(/\/+$/, "");

/**
 * Where the new backend runs (`PMO-Backend`, generated by Soul). Empty until it
 * is deployed, and the `/backend` rewrite is only added once it is set.
 *
 * New API code calls `/backend/...`; screens not yet rewired keep calling
 * `/api/...`. Like the legacy rewrite, this keeps every call on this app's
 * origin, so the sign-in cookie and Authorization header reach both backends.
 */
const backendUrl = (process.env.BACKEND_URL || "").replace(/\/+$/, "");

const nextConfig: NextConfig = {
  async redirects() {
    return [
      { source: "/dashboard", destination: "/analytics/dashboard", permanent: false },
      { source: "/reports", destination: "/analytics/reports", permanent: false },
    ];
  },
  async rewrites() {
    return [
      { source: "/api/:path*", destination: `${legacyApiUrl}/api/:path*` },
      ...(backendUrl ? [{ source: "/backend/:path*", destination: `${backendUrl}/:path*` }] : []),
    ];
  },
};

export default nextConfig;
